INSERT INTO `cms_content` VALUES ('1787212335907001529', '2787212335907000302', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQP-0085</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品名称</th><td>Recombinant Human IFN  gamma (E. coli)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品别称</th><td>Interferon Gamma; IFN-Gamma; Immune Interferon; IFNG</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">规格</th><td>10μg/50μg/500μg/1mg</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">蛋白编号</th><td>P01579</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">分子量</th><td>16.88 KDa</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">表观分子量</th><td>16 KDa, reducing conditions</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">内毒素</th><td>&lt; 0.01 EU/µg as determined by LAL test.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">纯度(SDS-PAGE)</th><td>Greater than 95% as determined by reducing SDS-PAGE. (QC verified)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">剂型描述</th><td>Lyophilized from a 0.2 μm filtered solution of 20mM PB, 5% Sucrose, 4% Mannitol, 0.02% Tween 80, pH7.4.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">复溶说明</th><td>Always centrifuge tubes before opening.Do not mix by vortex or pipetting.<br/>It is not recommended to reconstitute to a concentration less than 100μg/ml.<br/>Dissolve the lyophilized protein in distilled water.<br/>Please aliquot the reconstituted solution to minimize freeze-thaw cycles. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">运输条件</th><td>The product is shipped at ambient temperature.<br/>Upon receipt, store it immediately at the temperature listed below.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">保存条件</th><td>Lyophilized protein should be stored at ≤ -20°C, stable for one year after receipt.<br/>Reconstituted protein solution can be stored at 2-8°C for 2-7 days.<br/>Aliquots of reconstituted samples are stable at ≤ -20°C for 3 months.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品描述</th><td>Recombinant Human Interferon Gamma is produced by our E.coli expression system and the target gene encoding Gln24-Gln166 is expressed.</td></tr></tbody></table></div>', 'Recombinant Human IFN  gamma (E. coli)', 'BQP-0085', 'BQP-0085,Recombinant Human IFN  gamma (E. coli)', 'Recombinant Human Interferon Gamma is produced by our E.coli expression system and the target gene encoding Gln24-Gln166 is expressed.', '[{\"uid\": 1787215941691, \"url\": \"/upload/1/bioquanti/shengwu_shengchan.webp\", \"name\": \"shengwu_shengchan.webp\", \"path\": \"/upload/1/bioquanti/shengwu_shengchan.webp\", \"status\": \"success\"}]', 'BioQuanti', 'bioquanti', '0', '', 0, '', '2026-08-17 03:52:17', 0, '', 0, '2026-08-21 14:45:46', 0, '57', '2026-08-20 15:52:15', '57', 0);
INSERT INTO `cms_content` VALUES ('1787212335907001530', '2787212335907000302', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQP-0086</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品名称</th><td>Recombinant Human IFN alpha1 (C-6His)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品别称</th><td>Interferon alpha-1/13; IFN-alpha-1/13; Interferon alpha-D; LeIF D; IFNA1; IFNA13</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">规格</th><td>10μg/50μg/500μg/1mg</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">蛋白编号</th><td>P01562</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">分子量</th><td>20.4 KDa</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">表观分子量</th><td>17 KDa, reducing conditions</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">内毒素</th><td>&lt; 1 EU/µg as determined by LAL test.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">纯度(SDS-PAGE)</th><td>Greater than 95% as determined by reducing SDS-PAGE. (QC verified)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">剂型描述</th><td>Lyophilized from a 0.2 μm filtered solution of 20mM PB, 150mM NaCl, pH 7.4.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">复溶说明</th><td>Always centrifuge tubes before opening.Do not mix by vortex or pipetting.<br/>It is not recommended to reconstitute to a concentration less than 100μg/ml.<br/>Dissolve the lyophilized protein in distilled water.<br/>Please aliquot the reconstituted solution to minimize freeze-thaw cycles. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">运输条件</th><td>The product is shipped at ambient temperature.<br/>Upon receipt, store it immediately at the temperature listed below.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">保存条件</th><td>Lyophilized protein should be stored at ≤ -20°C, stable for one year after r