INSERT INTO `cms_content` VALUES ('1787212335907001560', '2787212335907000302', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQP-0116</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品名称</th><td>Recombinant Human IL-18BP (C-Fc)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品别称</th><td>Interleukin-18-binding protein; Tadekinig-alfa and IL18BP</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">规格</th><td>10μg/50μg/500μg/1mg</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">蛋白编号</th><td>O95998</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">分子量</th><td>44.8 KDa</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">表观分子量</th><td>60-75 KDa, reducing conditions</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">内毒素</th><td>&lt; 1 EU/µg as determined by LAL test.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">纯度(SDS-PAGE)</th><td>Greater than 95% as determined by reducing SDS-PAGE. (QC verified)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">剂型描述</th><td>Lyophilized from a 0.2 μm filtered solution of PBS, pH 7.4.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">复溶说明</th><td>Always centrifuge tubes before opening.Do not mix by vortex or pipetting.<br/>It is not recommended to reconstitute to a concentration less than 100μg/ml.<br/>Dissolve the lyophilized protein in distilled water.<br/>Please aliquot the reconstituted solution to minimize freeze-thaw cycles. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">运输条件</th><td>The product is shipped at ambient temperature.<br/>Upon receipt, store it immediately at the temperature listed below.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">保存条件</th><td>Lyophilized protein should be stored at ≤ -20°C, stable for one year after receipt.<br/>Reconstituted protein solutio