INSERT INTO `cms_content` VALUES ('1787212335907001578', '2787212335907000302', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQP-0134</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品名称</th><td>Recombinant Human IL-20RB (C-Fc)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品别称</th><td>Interleukin-20 receptor subunit beta; IL-20 receptor subunit beta; IL-20R-beta; IL-20RB; IL-20R2; DIRS1; hCG_2022374; FNDC6; MGC34923;  fibronectin type III domain containing 6; interleukin-20 receptor II</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">规格</th><td>10μg/50μg/500μg/1mg</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">蛋白编号</th><td>Q6UXL0</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">分子量</th><td>49.6 KDa</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">表观分子量</th><td>60-85 KDa, reducing conditions</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">内毒素</th><td>&lt; 1 EU/µg as determined by LAL test.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">纯度(SDS-PAGE)</th><td>Greater than 90% as determined by reducing SDS-PAGE. (QC verified)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">剂型描述</th><td>Supplied as a 0.2 μm filtered solution of 20mM PB, 150mM NaCl, pH 7.4.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">运输条件</th><td>The product is shipped on dry ice/polar packs.<br/>Upon receipt, store it immediately at the temperature listed below.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">保存条件</th><td>Store at ≤-70°C, stable for 6 months after receipt.<br/>Store at ≤-70°C, stable for 3 months under sterile conditions after opening. <br/>Please minimize freeze-thaw cycles.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品描述</th><td>Recombinant Human Interleukin-20 Receptor Subunit Beta/IL-20RB is produced b