INSERT INTO `cms_content` VALUES ('1787212335907001674', '2787212335907000302', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQP-0230</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品名称</th><td>Recombinant Human/Mouse/Rat BMP-2</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品别称</th><td>Bone Morphogenetic Protein 2; BMP-2; Bone Morphogenetic Protein 2A; BMP-2A; BMP2; BMP2A</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">规格</th><td>10μg/50μg/500μg/1mg</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">蛋白编号</th><td>P12643</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">分子量</th><td>13.3 KDa</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">表观分子量</th><td>13 KDa, reducing conditions</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">内毒素</th><td>&lt; 0.01 EU/µg as determined by LAL test.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">纯度(SDS-PAGE)</th><td>Greater than 95% as determined by reducing SDS-PAGE. (QC verified)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">剂型描述</th><td>Lyophilized from a 0.2 μm filtered solution of 10mM HAc-NH&lt;sub&gt;4&lt;/sub&gt;Ac, 4% D-Mannitol, pH 4.0.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">复溶说明</th><td>Always centrifuge tubes before opening.Do not mix by vortex or pipetting.<br/>It is not recommended to reconstitute to a concentration less than 100μg/ml.<br/>Dissolve the lyophilized protein in 50mM Acetic Acid.<br/>Please aliquot the reconstituted solution to minimize freeze-thaw cycles. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">运输条件</th><td>The product is shipped at ambient temperature.<br/>Upon receipt, store it immediately at the temperature listed below.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">保存条件</th><td>Lyophilized protein should be stored at ≤ -20°C, stable for one year after receipt.<br/>Reconstituted protein solution can be stored at 2-8°C for 2-7 days.<br/>Aliquots of reconstituted samples are stable at ≤ -20°C for 3 months.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品描述</th><td>Recombinant Human/Mouse/Rat Bone Morphogenetic Protein 2 is produced by our E.coli expression system and the target gene encoding Gln283-Arg396 is expressed.</td></tr></tbody></table></div>', 'Recombinant Human/Mouse/Rat BMP-2', 'BQP-0230', 'BQP-0230,Recombinant Human/Mouse/Rat BMP-2', 'Recombinant Human/Mouse/Rat Bone Morphogenetic Protein 2 is produced by our E.coli expression system and the target gene encoding Gln283-Arg396 is expressed.', '[{\"uid\": 1787215941836, \"url\": \"/upload/1/bioquanti/yangben.webp\", \"name\": \"yangben.webp\", \"path\": \"/upload/1/bioquanti/yangben.webp\", \"status\": \"success\"}]', 'BioQuanti', 'bioquanti', '0', '', 0, '', '2026-08-11 02:52:17', 0, '', 0, '2026-08-21 14:45:46', 0, '57', '2026-08-20 15:52:15', '57', 0);
