INSERT INTO `cms_content` VALUES ('1787212335907001730', '2787212335907000302', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQP-0286</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品名称</th><td>Recombinant Mouse IL-18 (N-6His)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品别称</th><td>Interleukin-18; Il18; Interferon gamma-inducing factor; IFN-gamma-inducing factor; Interleukin-1 gamma; IL-1 gamma; Igif</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">规格</th><td>10μg/50μg/500μg/1mg</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">蛋白编号</th><td>P70380</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">分子量</th><td>19.7 KDa</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">表观分子量</th><td>20 KDa, reducing conditions</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">内毒素</th><td>&lt; 1 EU/µg as determined by LAL test.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">纯度(SDS-PAGE)</th><td>Greater than 95% as determined by reducing SDS-PAGE. (QC verified)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">剂型描述</th><td>Lyophilized from a 0.2 μm filtered solution of 20mM Tris-HCl, 10% Trehalose, 50mM NaCl, 0.1mM EDTA, 0.05% Tween 80, pH 8.0.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">复溶说明</th><td>Always centrifuge tubes before opening.Do not mix by vortex or pipetting.<br/>It is not recommended to reconstitute to a concentration less than 100μg/ml.<br/>Dissolve the lyophilized protein in distilled water.<br/>Please aliquot the reconstituted solution to minimize freeze-thaw cycles. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">运输条件</th><td>The product is shipped at ambient temperature.<br/>Upon receipt, store it immediately at the temperature listed below.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">保存条件</