INSERT INTO `cms_content` VALUES ('1787212335907001742', '2787212335907000302', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQP-0298</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品名称</th><td>Recombinant Mouse IL-3 (C-6His)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品别称</th><td>Interleukin-3; IL-3; Hematopoietic growth factor;Multipotential colony-stimulating factor; P-cell-stimulating factor; Il3; Il-3;Mast cell growth factor; MCGF</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">规格</th><td>10μg/50μg/500μg/1mg</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">蛋白编号</th><td>P01586</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">分子量</th><td>16.5 KDa</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">表观分子量</th><td>15-32 KDa, reducing conditions</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">内毒素</th><td>&lt; 0.01 EU/µg as determined by LAL test.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">纯度(SDS-PAGE)</th><td>Greater than 95% as determined by reducing SDS-PAGE. (QC verified)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">剂型描述</th><td>Lyophilized from a 0.2 μm filtered solution of PBS, pH 7.4.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">复溶说明</th><td>Always centrifuge tubes before opening.Do not mix by vortex or pipetting.<br/>It is not recommended to reconstitute to a concentration less than 100μg/ml.<br/>Dissolve the lyophilized protein in distilled water.<br/>Please aliquot the reconstituted solution to minimize freeze-thaw cycles. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">运输条件</th><td>The product is shipped at ambient temperature.<br/>Upon receipt, store it immediately at the temperature listed below.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">保存条件</th><td>Lyophilized protein should be stored at ≤ -20°C, stable for one year after receipt.<br/>Reconstituted protein solution can be stored at 2-8°C for 2-7 days.<br/>Aliquots of reconstituted samples are stable at ≤ -20°C for 3 months.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品描述</th><td>Recombinant Mouse Interleukin-3 is produced by our Mammalian expression system and the target gene encoding Ala27-Cys166 is expressed with a 6His tag at the C-terminus.</td></tr></tbody></table></div>', 'Recombinant Mouse IL-3 (C-6His)', 'BQP-0298', 'BQP-0298,Recombinant Mouse IL-3 (C-6His)', 'Recombinant Mouse Interleukin-3 is produced by our Mammalian expression system and the target gene encoding Ala27-Cys166 is expressed with a 6His tag at the C-terminus.', '[{\"uid\": 1787215941904, \"url\": \"/upload/1/bioquanti/shengwu_shengchan.webp\", \"name\": \"shengwu_shengchan.webp\", \"path\": \"/upload/1/bioquanti/shengwu_shengchan.webp\", \"status\": \"success\"}]', 'BioQuanti', 'bioquanti', '0', '', 0, '', '2026-08-08 06:52:17', 0, '', 0, '2026-08-21 14:45:46', 0, '57', '2026-08-20 15:52:15', '57', 0);
INSERT INTO `cms_content` VALUES ('1787212335907001743', '2787212335907000302', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQP-0299</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品名称</th><td>Recombinant Mouse IL-4</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品别称</th><td>Interleukin-4; B-cell IgG differentiation factor; B-cell growth factor 1; B-cell stimulatory factor 1; IGG1 induction factor; Lymphocyte stimulatory factor 1; IL-4; BSF-1</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">规格</th><td>10μg/50μg/500μg/1mg</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">蛋白编号</th><td>P07750</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">分子量</th><td>13.4 KDa</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">表观分子量</th><td>14 KDa, reducing conditions</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">内毒素</th><td>&lt; 1 EU/µg as determined by LAL test.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">纯度(SDS-PAGE)</th><td>Greater than 95% as determined by reducing SDS-PAGE. (QC verified)</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">剂型描述</th><td>Lyophilized from a 0.2 μm filtered solution of 20mM PB,5% Sucrose,4% Mannitol,0.1% PS-80，pH 6.5.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">复溶说明</th><td>Always centrifuge tubes before opening.Do not mix by vortex or pipetting.<br/>It is not recommended to reconstitute to a concentration less than 100μg/ml.<br/>Dissolve the lyophilized protein in distilled water.<br/>Please aliquot the reconstituted solution to minimize freeze-thaw cycles. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">运输条件</th><td>The product is shipped at ambient temperature.Upon receipt, store it immediately at the temperature listed below.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">保存条件</th><td>Lyophilized protein should be stored at ≤ -20°C, stable for one year after receipt.<br/>Reconstituted protein solution can be stored at 2-8°C for 2-7 days.<br/>Aliquots of reconstituted samples are stable at ≤ -20°C for 3 months.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">产品描述</th><td>Recombinant Mouse Interleukin-4 is produced by our E.coli expression system and the target gene encoding His23-Ser140 is expressed.</td></tr></tbody></table></div>', 'Recombinant Mouse IL-4', 'BQP-0299', 'BQP-0299,Recombinant Mouse IL-4', 'Recombinant Mouse Interleukin-4 is produced by our E.coli expression system and the target gene encoding His23-Ser140 is expressed.', '[{\"uid\": 1787215941905, \"url\": \"/upload/1/bioquanti/yangben.webp\", \"name\": \"yangben.webp\", \"path\": \"/upload/1/bioquanti/yangben.webp\", \"status\": \"success\"}]', 'BioQuanti', 'bioquanti', '0', '', 0, '', '2026-08-08 05:52:17', 0, '', 0, '2026-08-21 14:45:46', 0, '57', '2026-08-20 15:52:15', '57', 0);
