INSERT INTO `cms_content` VALUES ('1787212335907001812', '2787212335907000411', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQAP-0024</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">名称</th><td>Human BID ELISA Pair Set</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">中文名称</th><td>人 BID 酶联免疫配对抗体组合</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">种属</th><td>Human</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">靶分子</th><td>BID</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">应用</th><td>ELISA</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">线性范围</th><td>7.81-500</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">灵敏度</th><td>The minimum detectable dose of Human BID was determined to be approximately 7.8 pg/ml. This is defined as at least three times standard deviations above the mean optical density of 10 replicates of the zero standard.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">检测限</th><td>7.8 pg/ml</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">包被抗体</th><td>0.5 mg/mL of mouse anti-BID monoclonal antibody. Dilute to a working concentration of 2 μg/mL in CBS before coating. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">检测抗体</th><td>1.0 mg/mL mouse anti-BID monoclonal antibody conjugated to horseradish-peroxidase (HRP). Dilute to working concentration of 0.25 μg/mL in detection antibody dilution buffer before use. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">标准品</th><td>Reconstitute with 1 mL detection antibody dilution buffer. After reconstitution, store at -20℃ to -80℃ in a manual defrost freezer. A seven-point standard curve using 2-fold serial dilutions in sample dilution buffer, and a high standard of 0.5 ng/mL is recommended.</td></tr></tbody></table></div>', '人 BID 酶联免疫配对抗体组合', 'BQAP-0024', 'BQAP-0024,Human BID ELISA Pair Set,Human', 'Human BID ELISA Pair Set', '[{\"uid\": 1787215941974, \"url\": \"/upload/1/bioquanti/yangben.webp\", \"name\": \"yangben.webp\", \"path\": \"/upload/1/bioquanti/yangben.webp\", \"status\": \"success\"}]', 'BioQuanti', 'bioquanti', '0', '', 0, '', '2026-08-19 16:52:17', 0, '', 0, '2026-08-21 14:45:46', 0, '57', '2026-08-20 15:52:15', '57', 0);
