INSERT INTO `cms_content` VALUES ('1787212335907001980', '2787212335907000411', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQAP-0192</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">名称</th><td>Human IL6R / IL-6R / CD126 ELISA Pair Set</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">中文名称</th><td>人 IL6R / IL-6R / CD126 酶联免疫配对抗体组合</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">种属</th><td>Human</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">靶分子</th><td>IL6R</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">应用</th><td>ELISA</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">线性范围</th><td>46.88-3000</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">灵敏度</th><td>The minimum detectable dose of Human IL6R / IL-6R / CD126 was determined to be approximately 46.88 pg/ml. This is defined as at least three times standard deviations above the mean optical density of 10 replicates of the zero standard.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">检测限</th><td>46.88 pg/ml</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">包被抗体</th><td>1 mg/mL of mouse anti-Human IL6R / IL-6R / CD126 monoclonal antibody (in PBS, pH 7.4). Dilute to a working concentration of 2 μg/mL in PBS before coating. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">检测抗体</th><td>0.2 mg/mL of rabbit anti-Human IL6R / IL-6R / CD126 polyclonal  antibody conjugated to horseradish-peroxidase (HRP) (in PBS, 50 % HRP-Protector, pH 7.4, store at 4℃). Dilute to working concentration of 1 μg/mL in detection antibody dilution buffer before use.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">标准品</th><td>Reconstitute with 1 mL detection antibody dilution buffer. After reconstitution, store at -20℃ to -80℃ in a manual defrost freezer. A seven-point standard curve using 2-fold serial dilutions in sample dilution buffer, and a high standard of 3000 pg/mL is recommended.</td></tr></tbody></table></div>', '人 IL6R / IL-6R / CD126 酶联免疫配对抗体组合', 'BQAP-0192', 'BQAP-0192,Human IL6R / IL-6R / CD126 ELISA Pair Set,Human', 'Human IL6R / IL-6R / CD126 ELISA Pair Set', '[{\"uid\": 1787215942142, \"url\": \"/upload/1/bioquanti/yangben.webp\", \"name\": \"yangben.webp\", \"path\": \"/upload/1/bioquanti/yangben.webp\", \"status\": \"success\"}]', 'BioQuanti', 'bioquanti', '0', '', 0, '', '2026-08-12 16:52:17', 0, '', 0, '2026-08-21 14:45:46', 0, '57', '2026-08-20 15:52:15', '57', 0);
