INSERT INTO `cms_content` VALUES ('1787212335907002078', '2787212335907000411', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQAP-0290</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">名称</th><td>Human Transferrin / TF ELISA Pair Set</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">中文名称</th><td>人 Transferrin / TF 酶联免疫配对抗体组合</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">种属</th><td>Human</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">靶分子</th><td>TF</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">应用</th><td>ELISA</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">线性范围</th><td>15.63-1000</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">灵敏度</th><td>The minimum detectable dose of Human Transferrin / TF was determined to be approximately 31.25 pg/ml. This is defined as at least three times standard deviations above the mean optical density of 10 replicates of the zero standard.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">检测限</th><td>15.63 pg/ml</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">包被抗体</th><td>1 mg/mL of mouse anti-Human Transferrin / TF monoclonal antibody (in PBS, pH 7.4). Dilute to a working concentration of 2 μg/mL in PBS before coating. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">检测抗体</th><td>0.2 mg/mL of mouse anti-Human Transferrin / TF monoclonal antibody conjugated to horseradish-peroxidase (HRP) (in PBS, 50 % HRP-Protector, pH 7.4, store at 4℃). Dilute to working concentration of 0.5 μg/mL in dilution buffer before use. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">标准品</th><td>Reconstitute with 1 mL dilution buffer. After reconstitution, store at -20℃ to -80℃ in a manual defrost freezer. A seven-point standard curve using 2-fold serial dilutions in dilution buffer, and a high standar