INSERT INTO `cms_content` VALUES ('1787212335907002113', '2787212335907000411', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQAP-0325</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">名称</th><td>Mouse CLEC4N / CLEC6A / Dectin-2 ELISA Pair Set</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">中文名称</th><td>小鼠 CLEC4N / CLEC6A / Dectin-2 酶联免疫配对抗体组合</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">种属</th><td>Mouse</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">靶分子</th><td>CLEC4N</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">应用</th><td>ELISA</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">线性范围</th><td>62.5-4000</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">灵敏度</th><td>The minimum detectable dose of Mouse CLEC4N / Nkcl was determined to be approximately 62.5 pg/ml. This is defined as at least three times standard deviations above the mean optical density of 10 replicates of the zero standard.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">检测限</th><td>62.5 pg/ml</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">包被抗体</th><td>2 mg/mL of rabbit anti-mouse CLEC4N monoclonal antibody. Dilute to a working concentration of 1.0 μg/mL in CBS before coating. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">检测抗体</th><td>0.5 mg/mL rabbit anti-mouse CLEC4N polyclonal antibody conjugated to horseradish-peroxidase (HRP). Dilute to working concentration of 0.25 μg/mL in detection antibody dilution buffer before use.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">标准品</th><td>Reconstitute standard powder with 1 mL detection antibody dilution buffer. After reconstitution, store at -20℃ to -80℃ in a manual defrost freezer. A seven-point standard curve using 2-fold serial dilutions in sample dilution buffer, and a high standard of 4