INSERT INTO `cms_content` VALUES ('1787212335907002175', '2787212335907000411', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQAP-0387</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">名称</th><td>Rat MMP9 / MMP-9 / CLG4B ELISA Pair Set</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">中文名称</th><td>大鼠 MMP9 / MMP-9 / CLG4B 酶联免疫配对抗体组合</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">种属</th><td>Rat</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">靶分子</th><td>MMP9</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">应用</th><td>ELISA</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">线性范围</th><td>19.53-1250</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">灵敏度</th><td>The minimum detectable dose of Rat MMP9 / MMP-9 / CLG4B was determined to be approximately 19.53 pg/ml. This is defined as at least three times standard deviations above the mean optical density of 10 replicates of the zero standard.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">检测限</th><td>19.53 pg/ml</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">包被抗体</th><td>0.5 mg/mL of mouse anti-Rat MMP9 / MMP-9 / CLG4B monoclonal antibody (in PBS, pH 7.4). Dilute to a working concentration of 2 μg/mL in PBS before coating. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">检测抗体</th><td>0.2 mg/mL of rabbit anti-Rat MMP9 / MMP-9 / CLG4B polyclonal  antibody conjugated to horseradish-peroxidase (HRP) (in PBS, 50 % HRP-Protector, pH 7.4, store at 4℃). Dilute to working concentration of 0.5 μg/mL in detection antibody dilution buffer before use.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">标准品</th><td>Reconstitute with 1 mL detection antibody dilution buffer. After reconstitution, store at -20℃ to -80℃ in a manual defrost freezer. A seven-point standard curve using 2-fold serial dilutions in sample dilution buffer, and a high standard of 1250 pg/mL is recommended.</td></tr></tbody></table></div>', '大鼠 MMP9 / MMP-9 / CLG4B 酶联免疫配对抗体组合', 'BQAP-0387', 'BQAP-0387,Rat MMP9 / MMP-9 / CLG4B ELISA Pair Set,Rat', 'Rat MMP9 / MMP-9 / CLG4B ELISA Pair Set', '[{\"uid\": 1787215942337, \"url\": \"/upload/1/bioquanti/yangben.webp\", \"name\": \"yangben.webp\", \"path\": \"/upload/1/bioquanti/yangben.webp\", \"status\": \"success\"}]', 'BioQuanti', 'bioquanti', '0', '', 0, '', '2026-08-04 13:52:18', 0, '', 0, '2026-08-21 14:45:46', 0, '57', '2026-08-20 15:52:15', '57', 0);
INSERT INTO `cms_content` VALUES ('1787212335907002176', '2787212335907000411', '<div class=\"bq-spec\"><h3>产品参数</h3><table class=\"table table-bordered\" style=\"width:100%;border-collapse:collapse;\"><tbody><tr><th style=\"width:160px;background:#f4f8fc;\">货号</th><td>BQAP-0388</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">名称</th><td>Rat PCSK9/NARC1 ELISA Pair Set</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">中文名称</th><td>大鼠 PCSK9/NARC1 酶联免疫配对抗体组合</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">种属</th><td>Rat</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">靶分子</th><td>PCSK9</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">应用</th><td>ELISA</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">线性范围</th><td>23.44-1500</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">灵敏度</th><td>The minimum detectable dose of Rat PCSK9/NARC1 was determined to be approximately 23.44 pg/ml. This is defined as at least three times standard deviations above the mean optical density of 10 replicates of the zero standard.</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">检测限</th><td>23.44 pg/ml</td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">包被抗体</th><td>0.5 mg/mL of mouse anti-Rat PCSK9/NARC1 monoclonal antibody (in PBS, pH 7.4). Dilute to a working concentration of 2 μg/mL in PBS before coating. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">检测抗体</th><td>0.2 mg/mL of rabbit anti-Rat PCSK9/NARC1 monoclonal antibody conjugated to horseradish-peroxidase (HRP) (in PBS, 50 % HRP-Protector, pH 7.4, store at 4℃). Dilute to working concentration of 0.5 μg/mL in detection antibody dilution buffer before use. </td></tr><tr><th style=\"width:160px;background:#f4f8fc;\">标准品</th><td>Reconstitute with 1 mL detection antibody dilution buffer. After reconstitution, store at -20℃ to -80℃ in a manual defrost freezer. A seven-point standard curve using 2-fold serial dilutions in sample dilution buffer, and a high standard of 1500 pg/mL is recommended.</td></tr></tbody></table></div>', '大鼠 PCSK9/NARC1 酶联免疫配对抗体组合', 'BQAP-0388', 'BQAP-0388,Rat PCSK9/NARC1 ELISA Pair Set,Rat', 'Rat PCSK9/NARC1 ELISA Pair Set', '[{\"uid\": 1787215942338, \"url\": \"/upload/1/bioquanti/2.jpg\", \"name\": \"2.jpg\", \"path\": \"/upload/1/bioquanti/2.jpg\", \"status\": \"success\"}]', 'BioQuanti', 'bioquanti', '0', '', 0, '', '2026-08-04 12:52:18', 0, '', 0, '2026-08-21 14:45:46', 0, '57', '2026-08-20 15:52:15', '57', 0);
